import chess
b = chess.Board('r4rk1/1pp2ppp/p1p1b2B/4N3/8/6Q1/PPP3PP/RN4K1 b - - 0 17')

def consequences(board, uci):
    board.push_uci(uci)
    # white's most damaging checks / captures
    checks = []
    caps = []
    for m in board.legal_moves:
        if board.gives_check(m):
            board.push(m)
            mate = board.is_checkmate()
            board.pop()
            checks.append((m.uci(), 'MATE' if mate else 'check'))
        elif board.is_capture(m):
            caps.append(m.uci())
    board.pop()
    return checks, caps

# examine all legal moves; flag those allowing mate or losing material immediately
for m in list(b.legal_moves):
    checks, caps = consequences(b, m.uci())
    mates = [c for c in checks if c[1]=='MATE']
    if mates:
        print(f'{m.uci():7} ALLOWS MATE {mates}')
    elif checks:
        print(f'{m.uci():7} allows checks {checks} caps {caps[:8]}')
    else:
        # material change available to white via capture
        print(f'{m.uci():7} safe-from-mate caps {caps[:10]}')
